from collections import deque
G=[[0]*14 for _ in range(15)]
G[0][6]=2
G[2]=[8,8,8,8,0,8,8,8,8,8,8,8,8,8]
G[4]=[8,8,0,8,8,8,8,0,8,8,8,0,8,8]
G[7]=[8,8,0,8,8,8,8,8,8,0,8,8,8,8]
G[10]=[8,8,8,8,0,8,8,0,8,8,8,0,8,8]
# fill reachable blank cells from source, but only propagate through zero rows/cols and don't traverse barriers
q=deque([(0,6)]); seen={(0,6)}
while q:
 r,c=q.popleft()
 for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
  nr,nc=r+dr,c+dc
  if 0<=nr<15 and 0<=nc<14 and G[nr][nc]!=8 and (nr,nc) not in seen:
   seen.add((nr,nc)); q.append((nr,nc))
print('reach',len(seen));
for r,c in seen: G[r][c]=2
for row in G: print(row)

